/* A stand-in for the 48 kHz resampler's filter (uac_fir.h, generated by Felucca's tools), so the host tests can
 * build usb.c with FELUCCA_UAC_48K=1 for its descriptors. All taps zero: not for listening. */
#define UAC_FIR_N 16u
#define UAC_FIR_L 160u
#define UAC_FIR_Q 30
static const int32_t UAC_FIR[UAC_FIR_L / 2u][UAC_FIR_N];
#define UAC_FIR_M 147u
